-- FRM-207 (draft): "Bought from" lists the APPROVED suppliers, read live from FRM-202.
--
-- It was a fixed list - Sysco, Restaurant Depot - with allowOther set. allowOther is not rendered
-- anywhere, so the list was closed: a third supplier could not be recorded without editing the
-- form, and the list could drift from the approved register the moment a supplier was added there.
--
-- Now the field carries SelectField.optionsFrom (added in this PR): it offers the supplier_name of
-- every SUBMITTED FRM-202 entry whose supplier_status is Approved or Conditionally Approved - the
-- same condition REP-201 Approved Supplier Register uses, copied from REP-201's own filters so the
-- two cannot disagree. Approving a supplier on FRM-202 is what makes it choosable here; a draft
-- approval, or a Rejected supplier, is not offered. That is SOP-2.3.4 enforced by the form rather
-- than by memory.
--
-- A value saved earlier that later drops off the list is kept and shown flagged, never removed.
--
-- FRM-207 is an unissued draft with no entries, so this is an edit to the draft, not a revision.
-- Guarded on the md5 of the live form_schema.

begin;

do $guard$
declare h text; st text; rev text; n int;
begin
  select md5((content->'form_schema')::text), status, revision into h, st, rev
    from public.sop_documents where sop_number = 'FRM-207';
  if (st, rev) is distinct from ('draft', 'New') then raise exception 'FRM-207 is %/%, expected draft/New.', st, rev; end if;
  if h <> '2bcc54cd1cc4b2dc9f655d5846087dd3' then raise exception 'FRM-207 form_schema changed since this was written (md5 %).', h; end if;
  select count(*) into n from public.sop_document_responses x join public.sop_documents d on d.id = x.document_id
   where d.sop_number = 'FRM-207';
  if n <> 0 then raise exception 'FRM-207 has % entries; re-check before changing a field they answer.', n; end if;
end $guard$;

update public.sop_documents
   set content = jsonb_set(content, '{form_schema}', $fs${"sections": [{"id": "material", "title": "1. The material", "fields": [{"id": "how_this_works", "text": "ONE ENTRY IS ONE MATERIAL AS APPROVED: a named product from a named manufacturer. The Entries list is the specification library - material, category, manufacturer and whether it is current - and each entry carries the manufacturer's specification sheet and allergen statement as attachments.\n\nWHAT 2.3.2.2 ASKS FOR. Specifications for all raw materials and packaging that impact finished product safety - ingredients, additives, processing aids, packaging and hazardous chemicals - documented and kept current.\n\nWHY THE BRAND IS PART OF IT. SOP-2.3.4 approves a material bought through a distributor as a named product from a named manufacturer. The approved brand recorded here is what the Brand / Manufacturer column on FRM-301 is checked against at every delivery. A different brand is a new material: record it under Approved alternates only once its allergens have been checked.\n\nA DISCONTINUED MATERIAL STAYS ON THE REGISTER, marked Discontinued. Deleting it would leave no record of what was specified when it was in use.", "type": "info", "label": "How this register works"}, {"id": "material_name", "help": "The site's own name for it, e.g. \"Creme cake base\", \"High-ratio cake flour\".", "type": "text", "label": "Material", "width": "half", "required": true, "showInList": true}, {"id": "category", "type": "select", "label": "Category", "width": "half", "options": ["Ingredient", "Additive / flavouring", "Processing aid", "Packaging - food contact", "Packaging - not food contact", "Hazardous chemical"], "required": true, "showInList": true}, {"id": "status", "type": "select", "label": "Status", "width": "third", "options": ["Current", "Under review", "Discontinued"], "required": true, "showInList": true}, {"id": "used_in", "help": "The products or process steps that use it.", "type": "textarea", "label": "Where it is used"}]}, {"id": "source", "title": "2. Approved source", "fields": [{"id": "source_info", "text": "Use the camera on this section to photograph the product's label: the manufacturer, product name, item code and pack size are read off it. Check each value before saving.\n\nBOUGHT FROM is the distributor or supplier, chosen from the approved supplier register: the list is every supplier with a submitted FRM-202 approval, so a supplier appears here once it has been approved there. THE MANUFACTURER is the brand on the pack.", "type": "info", "label": "Photograph the pack to fill this section"}, {"id": "manufacturer", "type": "text", "label": "Manufacturer / brand", "width": "half", "required": true, "scanFact": "brand", "showInList": true}, {"id": "manufacturer_product", "type": "text", "label": "Manufacturer's product name", "width": "half", "required": true, "scanFact": "product_name"}, {"id": "item_code", "type": "text", "label": "Manufacturer / distributor item code", "width": "third", "scanFact": "item_code"}, {"id": "pack_size", "type": "text", "label": "Pack size", "width": "third", "scanFact": "pack_size"}, {"id": "bought_from", "type": "select", "label": "Bought from", "width": "third", "options": [], "multiple": true, "required": true, "scanFact": "none", "optionsFrom": {"form": "FRM-202", "field": "supplier_name", "filters": [{"op": "in", "field": "supplier_status", "values": ["APPROVED – meets all documentation or recognized-distributor requirements.", "CONDITIONALLY APPROVED – lacks one or more documents but poses low food-safety risk (recognized distributor)."]}], "emptyText": "No supplier has a submitted approval yet. Approve the supplier on FRM-202 and submit it; it then appears here."}, "help": "Only suppliers with a submitted FRM-202 approval (Approved or Conditionally Approved) can be chosen - the same list as REP-201."}, {"id": "alternates", "help": "Other brands accepted for this material. A brand is added here only after its allergen declaration has been checked against Section 4; if its allergens differ, it needs the SQF Practitioner's review first, because the allergen statement on finished product may have to change.", "rows": {"mode": "dynamic", "addLabel": "Add alternate brand"}, "type": "grid", "label": "Approved alternates", "columns": [{"id": "brand", "type": "text", "label": "Manufacturer / brand", "width": 3}, {"id": "product", "type": "text", "label": "Product name / code", "width": 3}, {"id": "allergens_same", "type": "select", "label": "Allergens vs approved", "width": 2, "options": ["Same", "Different - reviewed"]}, {"id": "approved_on", "type": "date", "label": "Approved on", "width": 2}, {"id": "notes", "type": "text", "label": "Notes", "width": 3}]}], "scanMode": "ingredient", "scanLabel": true}, {"id": "specification", "title": "3. Specification (2.3.2.2)", "fields": [{"id": "spec_info", "text": "ATTACH THE MANUFACTURER'S SPECIFICATION SHEET to this entry - the Attachments section is at the bottom. For a branded product bought through a distributor this document takes the place of a certificate of analysis for each lot, which a distributor does not issue.\n\nWhere no specification exists - common for commodity items - record what the site specifies instead in the description below, and say so. A blank is not a specification.", "type": "info", "label": "What the specification is"}, {"id": "spec_on_file", "type": "select", "label": "Manufacturer specification", "width": "half", "options": ["Attached to this entry", "Held elsewhere - named below", "Requested, not yet received", "None issued - site specification below"], "required": true}, {"id": "spec_location", "type": "text", "label": "Where it is held", "width": "half"}, {"id": "spec_issue_date", "help": "The date printed on the manufacturer's sheet, so a newer one can be recognised.", "type": "date", "label": "Specification issue date", "width": "third"}, {"id": "description", "help": "What the material is and what it must be - form, colour, key limits the manufacturer states.", "type": "textarea", "label": "Description and key characteristics", "required": true}, {"id": "storage", "type": "select", "label": "Storage", "width": "third", "options": ["Ambient", "Chilled - at or below 40°F", "Frozen"], "required": true}, {"id": "shelf_life", "help": "Unopened, as stated by the manufacturer; and once opened, where it differs.", "type": "text", "label": "Shelf life", "width": "third"}]}, {"id": "allergens", "title": "4. Allergens", "fields": [{"id": "allergen_info", "text": "Record what the manufacturer's allergen statement or ingredient list declares - including any \"may contain\" or \"made in a facility with\" statement. These are the figures an alternate brand is checked against at receipt, and they feed the allergen statement on finished product.", "type": "info", "label": "Read the declaration, not the product name"}, {"id": "allergens_contains", "type": "select", "label": "Contains", "options": ["Milk", "Egg", "Wheat", "Soy", "Peanut", "Tree nuts", "Sesame", "Fish", "Crustacean shellfish", "None of the major allergens", "Not applicable - not a food ingredient"], "multiple": true, "required": true}, {"id": "may_contain", "help": "Word for word from the pack or statement. Write \"none\" where there is none.", "type": "textarea", "label": "May contain / precautionary statement"}, {"id": "allergen_statement", "type": "select", "label": "Allergen statement", "width": "half", "options": ["Attached to this entry", "On the specification sheet", "Taken from the pack label - photo attached", "Not applicable - not a food ingredient"], "required": true}]}, {"id": "review", "title": "5. Review and approval", "fields": [{"id": "review_info", "text": "2.3.2.2 requires specifications to be KEPT CURRENT. Review each entry at least annually and whenever the manufacturer issues a new sheet, changes the product, or a different brand is bought. Ask the supplier to tell the site of any change in composition - allergens especially - and record that it was asked.", "type": "info", "label": "Keeping it current"}, {"id": "change_notice", "type": "select", "label": "Supplier asked to notify changes in composition", "width": "half", "options": ["Yes - recorded", "Not yet"]}, {"id": "next_review", "type": "date", "label": "Next review of this entry", "width": "half", "required": true}, {"id": "approved_by", "role": "verifier", "type": "signature", "label": "Reviewed and approved by the SQF Practitioner", "required": true, "statement": "This specification is current, the manufacturer and product named are the ones approved for this material, and the allergens recorded match the manufacturer's declaration."}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{material_name} — {manufacturer}"}, "schemaVersion": 1}$fs$::jsonb)
 where sop_number = 'FRM-207';

do $verify$
declare bf jsonb; rep jsonb;
begin
  select f into bf from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
         jsonb_array_elements(s->'fields') f where d.sop_number = 'FRM-207' and f->>'id' = 'bought_from';
  select content->'report_schema'->'filters' into rep from public.sop_documents where sop_number = 'REP-201';
  if bf->'optionsFrom'->>'form' <> 'FRM-202' or bf->'optionsFrom'->>'field' <> 'supplier_name' then
    raise exception 'bought_from is not linked to FRM-202 supplier_name.';
  end if;
  if bf->'optionsFrom'->'filters' <> rep then
    raise exception 'bought_from filters differ from REP-201''s - the two registers would disagree.';
  end if;
  if jsonb_array_length(bf->'options') <> 0 or bf ? 'allowOther' or not (bf->>'multiple')::boolean
     or not (bf->>'required')::boolean or bf->>'scanFact' <> 'none' then
    raise exception 'bought_from lost a setting: %', bf;
  end if;
  raise notice 'FRM-207: Bought from now lists approved FRM-202 suppliers.';
end $verify$;

commit;
